import { renderLanding } from './landing.js';
import { $, i, icons, toast, reportError, busy, modal, closeModal, toggleTheme } from './ui.js';
import { db, configured, getConfig, session, currentProfile, rpc } from './api.js';
import { escapeHTML as h, safePublicConfig, friendlyError } from './utils.js';
import { googleSignInURL, registerWithoutConfirmation, readOAuthFailure } from './auth-flow.js';
import { homeFor, requestedRole } from './access.js';
import { authenticatedUser, signOut } from './session.js';
export { homeFor } from './access.js';
export function openConnectionSettings() {
  const cfg=getConfig();modal('Connect your Supabase project',`<p class="muted-note">Run the supplied SQL migration and deploy the save-expense Edge Function first. Only enter public browser credentials here. A service-role or secret key must never be used.</p><form id="connection-form" class="form-grid"><div class="field full"><label for="project-url">Project URL</label><input id="project-url" type="url" required value="${h(cfg.supabaseUrl||'')}" placeholder="https://your-project.supabase.co"></div><div class="field full"><label for="project-key">Public publishable / anon key</label><input id="project-key" required value="${h(cfg.supabaseKey||'')}" placeholder="sb_publishable_…" autocomplete="off"></div><div class="field full"><button class="button primary" type="submit">Save configuration & reload</button></div></form>`);
  $('#connection-form').onsubmit=e=>{e.preventDefault();const cfg={supabaseUrl:$('#project-url').value.trim().replace(/\/$/,''),supabaseKey:$('#project-key').value.trim(),configVersion:window.EXPENSEFLOW_CONFIG?.configVersion};if(!safePublicConfig(cfg))return toast('Enter a valid HTTPS project URL and a public publishable or anon key. Secret keys are rejected.','error');localStorage.setItem('expenseflow-public-config',JSON.stringify(cfg));location.reload();};
}
export function landing() { renderLanding(openConnectionSettings); }
export async function authPage(route) {
  const callbackFailure=['login','register'].includes(route)?readOAuthFailure(location.href):null;
  let initialError=callbackFailure?.message||'';
  if(callbackFailure)history.replaceState(null,'',callbackFailure.cleanURL);
  const openWorkspace=async(userID)=>{
    let profile;
    try{profile=await currentProfile(userID);}catch(error){throw new Error('You are signed in, but your workspace profile could not load. '+friendlyError(error));}
    let intent;try{intent=JSON.parse(sessionStorage.getItem('expenseflow-oauth-role')||'null');}catch{/* No registration intent. */}
    if(intent&&Date.now()-intent.createdAt<1800000&&profile.role==='employee'&&['manager','finance'].includes(intent.role))await rpc('request_workspace_role',{p_role:intent.role});
    try{sessionStorage.removeItem('expenseflow-oauth-role');}catch{/* Storage disabled. */}
    location.replace(homeFor(profile.role));
  };
  if(configured()&&route!=='reset-password'&&!callbackFailure){try{const user=await authenticatedUser();if(user){await openWorkspace(user.id);return;}}catch(e){initialError=friendlyError(e);}}
  const register=route==='register',forgot=route==='forgot-password',reset=route==='reset-password';
  const title=register?'Your workspace starts here.':forgot?'Forgot your password?':reset?'Choose a new password.':'Welcome back.';
  const subtitle=register?'Choose your workspace role. Manager and finance access require administrator approval.':forgot?'We’ll email you a secure password reset link.':reset?'Use a strong password to protect your account.':'Sign in to your company’s expense workspace.';
  $('#app').innerHTML=`<div class="auth-layout"><aside class="auth-brand-panel"><a href="index.html" class="brand"><span class="brand-mark">ef</span><span>Expense<span class="brand-light">Flow</span></span></a><div class="auth-pitch"><span class="hero-tag">ENTERPRISE EXPENSE MANAGEMENT</span><h1>Clear expenses.<br>Confident decisions.</h1><p>One connected workflow for employees, managers and finance teams.</p><div class="auth-benefit">${i('shield-check')} Secure, private receipt storage</div><div class="auth-benefit">${i('git-pull-request')} Accountability at every approval</div><div class="auth-benefit">${i('chart-no-axes-combined')} The complete picture of your spending</div></div><small>ExpenseFlow · College project demonstration</small></aside><section class="auth-form-panel"><div class="auth-top"><a href="index.html">${i('arrow-left')} Back to home</a><button id="auth-theme" class="icon-button" aria-label="Toggle theme">${i('moon')}</button></div><div class="auth-form-wrap"><div class="eyebrow">YOUR TEAM. YOUR WORKSPACE.</div><h2>${title}</h2><p>${subtitle}</p>${!configured()?`<div class="form-feedback"><strong>Backend setup needed.</strong> Connect your Supabase project before signing in. <button class="text-button" id="auth-configure">Configure project ${i('arrow-right')}</button></div>`:''}<div id="auth-message" class="form-feedback" hidden role="status"></div><form id="auth-form" class="form-grid">${register?roleSelection()+ '<div class="field full"><label for="full-name">Full name</label><input id="full-name" autocomplete="name" required maxlength="100" placeholder="Your full name"></div>':''}${!reset?'<div class="field full"><label for="email">Email address</label><input id="email" type="email" required autocomplete="email" placeholder="you@company.com"></div>':''}${!forgot?`<div class="field full"><label for="password">${reset?'New password':'Password'}</label><input id="password" type="password" required ${register||reset?'minlength="10"':''} autocomplete="${register||reset?'new-password':'current-password'}" placeholder="${register||reset?'At least 10 characters':'Enter your password'}"></div>`:''}${register||reset?'<div class="field full"><label for="confirm-password">Confirm password</label><input id="confirm-password" type="password" required autocomplete="new-password"></div>':''}${!register&&!forgot&&!reset?'<a class="forgot-link" href="forgot-password.html">Forgot password?</a>':''}<div class="field full"><button class="button primary auth-submit" type="submit" ${configured()?'':'disabled'}>${register?'Create account':forgot?'Send reset link':reset?'Update password':'Sign in'} ${i('arrow-right')}</button></div></form>${!forgot&&!reset?`<div class="auth-or"><span>or continue with</span></div><button class="button secondary google-button" id="google-login" ${configured()?'':'disabled'}><span class="google-g">G</span> Continue with Google</button><p class="auth-switch">${register?'Already have an account? <a href="login.html">Sign in</a>':'New to ExpenseFlow? <a href="register.html">Create an account</a>'}</p>`:'<p class="auth-switch"><a href="login.html">Return to sign in</a></p>'}<p class="auth-security">${i('lock-keyhole')} ${register?'New accounts receive employee access only.':'Authentication powered by Supabase'}</p><button class="text-button" id="change-config">Project configuration</button></div></section></div>`;
  $('#auth-theme').onclick=toggleTheme;$('#change-config').onclick=openConnectionSettings;if($('#auth-configure'))$('#auth-configure').onclick=openConnectionSettings;
  const message=(text,success=true)=>{const el=$('#auth-message');el.hidden=false;el.classList.toggle('success',success);el.setAttribute('role',success?'status':'alert');el.textContent=text;el.tabIndex=-1;el.focus();};
  const perform=(button,action)=>busy(button,async()=>{ $('#auth-message').hidden=true;try{await action();}catch(error){message(friendlyError(error),false);} });
  if(initialError)message(initialError,false);
  $('#auth-form').onsubmit=e=>{e.preventDefault();const button=e.submitter;perform(button,async()=>{
    if((register||reset)&&$('#password').value!==$('#confirm-password').value)throw new Error('The two passwords do not match.');
    if(register){const data=await registerWithoutConfirmation(db(),getConfig(),{email:$('#email').value.trim(),password:$('#password').value,fullName:$('#full-name').value.trim(),requestedRole:document.querySelector('input[name="requested-role"]:checked')?.value});await openWorkspace(data.user.id);}
    else if(forgot){const {error}=await db().auth.resetPasswordForEmail($('#email').value.trim(),{redirectTo:new URL('reset-password.html',location.href).href});if(error)throw error;message('If this email has an account, a reset link will arrive shortly. Check your inbox and spam folder.');}
    else if(reset){const s=await session();if(!s)throw new Error('Open a valid password-reset link from your email first.');const {error}=await db().auth.updateUser({password:$('#password').value});if(error)throw error;$('#auth-form').dataset.dirty='false';await signOut();}
    else {const {data,error}=await db().auth.signInWithPassword({email:$('#email').value.trim(),password:$('#password').value});if(error)throw error;await openWorkspace(data.user.id);}
  });};
  if($('#google-login'))$('#google-login').onclick=e=>perform(e.currentTarget,async()=>{const url=await googleSignInURL(db(),getConfig(),location.href);if(register){try{sessionStorage.setItem('expenseflow-oauth-role',JSON.stringify({role:requestedRole(document.querySelector('input[name="requested-role"]:checked')?.value),createdAt:Date.now()}));}catch{throw new Error('Enable browser session storage to continue registration with Google.');}}location.assign(url);});icons();
}

function roleSelection(){return `<fieldset class="role-choice-group full"><legend>How will you use ExpenseFlow?</legend><div class="role-choices">${[['employee','Employee','Submit expenses, upload receipts and track reimbursements.'],['manager','Manager','Review assigned team claims and approve valid expenses.'],['finance','Finance Administrator','Process approved reimbursements and manage payment records.']].map(([value,label,description])=>`<label class="role-choice"><input type="radio" name="requested-role" value="${value}" ${value==='employee'?'checked':''}><span><strong>${label}</strong><small>${description}</small></span></label>`).join('')}</div><p class="role-request-note">All new accounts begin with employee access. Manager and Finance Administrator requests appear in the administrator’s approval queue.</p></fieldset>`;}
